<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('documents.view');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$id=(int)($_GET['id']??0);$st=db()->prepare("SELECT d.*,p.name patient_name,p.primary_professional_id,u.name professional_name,u.professional_crp,t.name tenant_name FROM clinical_documents d JOIN patients p ON p.id=d.patient_id AND p.tenant_id=d.tenant_id JOIN users u ON u.id=d.professional_id AND u.tenant_id=d.tenant_id JOIN tenants t ON t.id=d.tenant_id WHERE d.id=:id AND d.tenant_id=:t AND d.status='signed'");$st->execute(['id'=>$id,'t'=>$user['tenant_id']]);$d=$st->fetch();if(!$d||!\App\Core\Rbac::canViewPatientClinical($user,$d)){http_response_code(403);exit('Documento indisponível.');}$c=\App\Core\Crypto::decrypt($d['content_enc'],true);audit('clinical.document_print','clinical_document',$id,[]);?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title><?=e($d['title'])?></title><style>body{font-family:Arial,sans-serif;max-width:800px;margin:45px auto;color:#222;line-height:1.65;padding:0 30px}header{border-bottom:1px solid #bbb;margin-bottom:35px;padding-bottom:16px}h1{font-size:22px}h2{font-size:14px;text-transform:uppercase;margin-top:28px}footer{margin-top:60px;border-top:1px solid #bbb;padding-top:20px;font-size:12px;color:#555}@media print{button{display:none}body{margin:0 auto}}</style></head><body><button id="print-document">Imprimir / salvar em PDF</button><header><strong><?=e($d['tenant_name'])?></strong><h1><?=e($d['title'])?></h1><div><?=e(ucfirst($d['document_type']))?></div></header><?php foreach($c as $k=>$v):?><h2><?=e(ucfirst(str_replace('_',' ',$k)))?></h2><p><?=nl2br(e($v))?></p><?php endforeach?><footer>Assinado em <?=e(date('d/m/Y H:i',strtotime($d['signed_at'])))?> por <?=e($d['professional_name'])?> <?=e($d['professional_crp']?:'')?>.<br>Validação: <?=e(url('validate.php?token='.$d['validation_token']))?></footer></body></html>
